(6216927, 917862, 108069, '<td valign="top">The blur suits this perfectly. Nice lighting. Moody and perfect for the challenge.</td>', 'The blur suits this perfectly. Nice lighting. Moody and perfect for the challenge.', '2010-11-08 18:30:26.000000', NULL, 1),
