(6218195, 916843, 97225, '<td valign="top">Congratulations on your well deserved blue ribbon. It''s a wonderful image.</td>', 'Congratulations on your well deserved blue ribbon. It''s a wonderful image.', '2010-11-10 00:21:12.000000', NULL, 0),
(6218196, 916843, 30861, '<td valign="top">You know, at the time of voting I wasn''t all that impressed with this, it seemed a bit of a "pretty yawner" to me, but it is growing on me now. Technically it''s just very well done. You got your flashes, me I just paint with a penlight LOL. Big congrats on the blue!</td>', 'You know, at the time of voting I wasn''t all that impressed with this, it seemed a bit of a "pretty yawner" to me, but it is growing on me now. Technically it''s just very well done. You got your flashes, me I just paint with a penlight LOL. Big congrats on the blue!', '2010-11-10 00:22:02.000000', NULL, 0),
(6218199, 917751, 117534, '<td valign="top">I knew this would do really well! What a GREAT score!!! Congratulations on a supberb top 10.. BTY Where is this and What is it?????</td>', 'I knew this would do really well! What a GREAT score!!! Congratulations on a supberb top 10.. BTY Where is this and What is it?????', '2010-11-10 00:22:46.000000', NULL, 0),
