(6218238, 917815, 54645, '<td valign="top">Well done Sara, congrats.</td>', 'Well done Sara, congrats.', '2010-11-10 00:34:01.000000', NULL, 0),
(6218240, 916798, 88235, '<td valign="top">I really like this picture... the blur in the boats makes me feel like I''m in a dream.  I was one of your 10''s</td>', 'I really like this picture... the blur in the boats makes me feel like I''m in a dream.  I was one of your 10''s', '2010-11-10 00:34:31.000000', NULL, 0),
